input.command:
cd /d/the-synaptic-sea-2d; awk '
{ s=$0; gsub(/\*\(Amended[^)]*\)\*/,"",s);
  while (match(s,/[0-9]+[a-z]? *… *[0-9]+[a-z]?/)) { r=substr(s,RSTART,RLENGTH); s=substr(s,1,RSTART-1) " " substr(s,RSTART+RLENGTH); split(r,p,/ *… */); a=p[1]; b=p[2]; an=a+0; bn=b+0;
     if (a ~ /[a-z]$/) { l1=substr(a,length(a)); l2=substr(b,length(b)); for(c=index("abcdefgh",l1);c<=index("abcdefgh",l2);c++) print an substr("abcdefgh",c,1) }
     else for(x=an;x<=bn;x++) print x ; }
  while (match(s,/[0-9]+[a-z]?/)) { print substr(s,RSTART,RLENGTH); s=substr(s,RSTART+RLENGTH) } }' /tmp/tbl.txt | sed -E 's/^0+([0-9])/\1/' | sort -u > /tmp/covered.txt
sed -E 's/^0+([0-9])/\1/' /tmp/ids.txt | sort -u > /tmp/ids2.txt
echo "defined but not in class table:"; comm -23 /tmp/ids2.txt /tmp/covered.txt | tr '\n' ' '

